fn quick_command_matches(query: &str, label: &str, keywords: &str) -> bool {
    let filter = query.trim().to_ascii_lowercase();
    filter.is_empty()
        || label.to_ascii_lowercase().contains(&filter)
        || keywords.to_ascii_lowercase().contains(&filter)
}

