    fn add_entity_with_type(&mut self, kind: &str) {
        let template_style = self
            .case
            .active_chart_template
            .and_then(|template_id| {
                self.case
                    .chart_templates
                    .iter()
                    .find(|template| template.id == template_id)
            })
            .and_then(|template| {
                template
                    .entity_styles
                    .iter()
                    .find(|style| style.kind.eq_ignore_ascii_case(kind))
            });
        let item = Entity {
            id: Uuid::new_v4(),
            name: "New entity".into(),
            kind: kind.into(),
            representation: template_style
                .map(|style| style.representation)
                .unwrap_or(EntityRepresentation::Icon),
            detail: String::new(),
            attributes: Vec::new(),
            sql_attribute_values: Vec::new(),
            sql_attribute_baselines: Vec::new(),
            aliases: Vec::new(),
            external_ids: Vec::new(),
            merged_records: Vec::new(),
            x: 0.5,
            y: 0.5,
            position_locked: false,
            color: template_style
                .map(|style| style.color)
                .unwrap_or([55, 128, 162]),
        };
        self.select_chart_entity(item.id, false);
        self.case.entities.push(item);
        self.duplicate_candidates.clear();
        self.invalidate_network_groups();
    }

    fn save_chart_template(&mut self) {
        let mut entity_styles = Vec::new();
        for entity in &self.case.entities {
            if entity.kind.trim().is_empty()
                || entity_styles
                    .iter()
                    .any(|style: &ChartTemplateEntityStyle| {
                        style.kind.eq_ignore_ascii_case(entity.kind.trim())
                    })
            {
                continue;
            }
            entity_styles.push(ChartTemplateEntityStyle {
                kind: entity.kind.trim().chars().take(128).collect(),
                representation: entity.representation,
                color: entity.color,
            });
            if entity_styles.len() == 64 {
                break;
            }
        }
        let mut relationship_types = Vec::new();
        for link in &self.case.links {
            let label = link.label.trim();
            if !label.is_empty()
                && !relationship_types
                    .iter()
                    .any(|known: &String| known.eq_ignore_ascii_case(label))
            {
                relationship_types.push(label.chars().take(128).collect());
            }
            if relationship_types.len() == 64 {
                break;
            }
        }
        let mut conditional_rules = Vec::new();
        for entry in self
            .case
            .labels
            .iter()
            .filter(|label| label.is_legend)
            .flat_map(|label| &label.legend_entries)
        {
            let has_attribute_class = entry
                .attribute_class
                .as_deref()
                .is_some_and(|attribute_class| !attribute_class.trim().is_empty());
            if entry.conditional_color
                && entry.symbol.is_attribute()
                && has_attribute_class
                && !conditional_rules.contains(entry)
            {
                conditional_rules.push(entry.clone());
            }
        }
        let conditional_rules_truncated =
            conditional_rules.len() > MAX_CHART_TEMPLATE_CONDITIONAL_RULES;
        conditional_rules.truncate(MAX_CHART_TEMPLATE_CONDITIONAL_RULES);
        if entity_styles.is_empty() && relationship_types.is_empty() && conditional_rules.is_empty()
        {
            self.status =
                "ADD A TYPED ITEM OR CONDITIONAL RULE BEFORE SAVING A CHART TEMPLATE".into();
            return;
        }
        let name: String = self
            .case
            .active_chart_title
            .trim()
            .chars()
            .take(64)
            .collect();
        if name.is_empty() {
            self.status = "CHART TEMPLATE NEEDS A NAME".into();
            return;
        }
        if let Some(existing) = self
            .case
            .chart_templates
            .iter_mut()
            .find(|template| template.name.eq_ignore_ascii_case(&name))
        {
            existing.entity_styles = entity_styles;
            existing.relationship_types = relationship_types;
            existing.conditional_rules = conditional_rules;
            existing.conditional_rules_truncated = conditional_rules_truncated;
            self.case.active_chart_template = Some(existing.id);
            self.status = chart_template_saved_status(
                "UPDATED",
                &name,
                existing.conditional_rules.len(),
                existing.conditional_rules_truncated,
            );
            return;
        }
        if self.case.chart_templates.len() >= 32 {
            self.status = "CASE TEMPLATE LIMIT REACHED · REMOVE A TEMPLATE BEFORE SAVING".into();
            return;
        }
        let template = ChartTemplate {
            id: Uuid::new_v4(),
            name: name.clone(),
            entity_styles,
            relationship_types,
            conditional_rules,
            conditional_rules_truncated,
        };
        let status = chart_template_saved_status(
            "SAVED",
            &name,
            template.conditional_rules.len(),
            template.conditional_rules_truncated,
        );
        self.case.active_chart_template = Some(template.id);
        self.case.chart_templates.push(template);
        self.status = status;
    }

    fn apply_chart_template(&mut self, template_id: Uuid) {
        let Some(template) = self
            .case
            .chart_templates
            .iter()
            .find(|template| template.id == template_id)
            .cloned()
        else {
            self.status = "CHART TEMPLATE NO LONGER EXISTS".into();
            return;
        };
        for entity in &mut self.case.entities {
            if let Some(style) = template
                .entity_styles
                .iter()
                .find(|style| style.kind.eq_ignore_ascii_case(&entity.kind))
            {
                entity.representation = style.representation;
                entity.color = style.color;
            }
        }
        self.case
            .labels
            .retain(|label| label.template_rules_for.is_none());
        let rule_chunks = template
            .conditional_rules
            .chunks(MAX_CHART_LEGEND_ENTRIES)
            .collect::<Vec<_>>();
        for (chunk_index, rules) in rule_chunks.iter().enumerate() {
            let truncated =
                template.conditional_rules_truncated && chunk_index + 1 == rule_chunks.len();
            let [x, y] = chart_legend_initial_position(&self.case, rules, truncated);
            self.case.labels.push(ChartLabel {
                id: Uuid::new_v4(),
                text: if rule_chunks.len() == 1 {
                    format!("{} · Rules", template.name)
                } else {
                    format!(
                        "{} · Rules {}/{}",
                        template.name,
                        chunk_index + 1,
                        rule_chunks.len()
                    )
                },
                x,
                y,
                font_size: 12.0,
                color: default_chart_label_color(),
                is_legend: true,
                legend_entries: rules.to_vec(),
                legend_entries_truncated: truncated,
                template_rules_for: Some(template_id),
            });
        }
        self.case.active_chart_template = Some(template_id);
        self.invalidate_network_groups();
        self.status = format!(
            "CHART TEMPLATE APPLIED · {} · {} CONDITIONAL RULES ACTIVE{}",
            template.name,
            template.conditional_rules.len(),
            if template.conditional_rules_truncated {
                " · SAVED RULE LIMIT REACHED"
            } else {
                ""
            }
        );
    }

    fn delete_chart_template(&mut self, template_id: Uuid) {
        let Some(template) = self
            .case
            .chart_templates
            .iter()
            .find(|template| template.id == template_id)
            .map(|template| template.name.clone())
        else {
            return;
        };
        self.case
            .chart_templates
            .retain(|template| template.id != template_id);
        self.case
            .labels
            .retain(|label| label.template_rules_for != Some(template_id));
        if self.case.active_chart_template == Some(template_id) {
            self.case.active_chart_template = None;
        }
        for chart in &mut self.case.chart_tabs {
            if chart.template_id == Some(template_id) {
                chart.template_id = None;
            }
            chart
                .labels
                .retain(|label| label.template_rules_for != Some(template_id));
        }
        self.status = format!("CHART TEMPLATE DELETED · {template}");
    }

