                            if ui.button("Reset view").clicked() {
                                self.chart_zoom = 1.0;
                                self.chart_pan = egui::Vec2::ZERO;
                                self.chart_focus = None;
                                self.chart_focus_link = None;
                                self.chart_fit_entities = None;
                                self.chart_fit_path = None;
                                self.chart_focus_group = None;
                                ui.close_menu();
                            }
