const MAX_XSLT_XML_BYTES: u64 = 16 * 1024 * 1024;

fn xslt_xml_contains_doctype(bytes: &[u8]) -> bool {
    const TOKEN: &[u8] = b"<!DOCTYPE";
    bytes
        .windows(TOKEN.len())
        .any(|window| window.eq_ignore_ascii_case(TOKEN))
        || bytes.windows(TOKEN.len() * 2).any(|window| {
            TOKEN
                .iter()
                .enumerate()
                .all(|(index, byte)| window[index * 2] == *byte && window[index * 2 + 1] == 0)
                || TOKEN
                    .iter()
                    .enumerate()
                    .all(|(index, byte)| window[index * 2] == 0 && window[index * 2 + 1] == *byte)
        })
}

fn transform_xml_with_xslt(input_path: &str, stylesheet_path: &str) -> Result<PathBuf, String> {
    fn validate_xml_source(path: &str, label: &str) -> Result<(), String> {
        let metadata =
            fs::metadata(path).map_err(|error| format!("cannot inspect {label}: {error}"))?;
        if metadata.len() > MAX_XSLT_XML_BYTES {
            return Err(format!("{label} exceeds the 16 MiB import limit"));
        }
        let bytes = fs::read(path).map_err(|error| format!("cannot read {label}: {error}"))?;
        if bytes.len() as u64 > MAX_XSLT_XML_BYTES {
            return Err(format!("{label} exceeds the 16 MiB import limit"));
        }
        if xslt_xml_contains_doctype(&bytes) {
            return Err(format!(
                "{label} must not contain a document type declaration"
            ));
        }
        Ok(())
    }

    let input_path = fs::canonicalize(input_path)
        .map_err(|error| format!("cannot resolve XML input: {error}"))?;
    let stylesheet_path = fs::canonicalize(stylesheet_path)
        .map_err(|error| format!("cannot resolve XSLT stylesheet: {error}"))?;
    validate_xml_source(&input_path.to_string_lossy(), "XML input")?;
    validate_xml_source(&stylesheet_path.to_string_lossy(), "XSLT stylesheet")?;
    let transformed_path =
        env::temp_dir().join(format!("arch-notebook-xslt-import-{}.anx", Uuid::new_v4()));
    let output = match Command::new("xsltproc")
        .args(["--nonet", "--nowrite", "--novalid"])
        .arg(stylesheet_path)
        .arg(input_path)
        .output()
    {
        Ok(output) => output,
        Err(error) => return Err(format!("cannot start xsltproc: {error}")),
    };
    if !output.status.success() {
        let detail = String::from_utf8_lossy(&output.stderr);
        return Err(format!("XSLT transformation failed: {}", detail.trim()));
    }
    if output.stdout.len() as u64 > MAX_XSLT_XML_BYTES {
        return Err("transformed ANX exceeds the 16 MiB import limit".into());
    }
    #[cfg(unix)]
    use std::os::unix::fs::OpenOptionsExt;
    let mut options = fs::OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    options.mode(0o600);
    let mut transformed_file = options
        .open(&transformed_path)
        .map_err(|error| format!("cannot create temporary transformed ANX: {error}"))?;
    if let Err(error) = transformed_file.write_all(&output.stdout) {
        let _ = fs::remove_file(&transformed_path);
        return Err(format!("cannot stage transformed ANX: {error}"));
    }
    drop(transformed_file);
    Ok(transformed_path)
}

fn import_xml_with_xslt_cli(
    case_path: &str,
    input_path: &str,
    stylesheet_path: &str,
    json_output: bool,
) -> Result<(), String> {
    let transformed_path = transform_xml_with_xslt(input_path, stylesheet_path)?;
    let result = (|| {
        import_interchange_cli(
            case_path,
            &transformed_path.to_string_lossy(),
            json_output,
            "ANX",
            Some(input_path),
        )
    })();
    let _ = fs::remove_file(&transformed_path);
    result
}

fn document_packet_value(packet: &serde_json::Value, key: &str) -> Result<String, String> {
    packet
        .get(key)
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_owned)
        .ok_or_else(|| format!("document packet is missing required string field {key:?}"))
}

fn validate_bounded_document_packet_value(
    value: &serde_json::Value,
    path: &str,
) -> Result<(), String> {
    const FORBIDDEN: &[&str] = &[
        "raw_pdf",
        "raw_pdf_bytes",
        "raw_ocr",
        "raw_ocr_text",
        "ocr_dump",
        "rendered_page_image",
        "page_image",
        "page_image_bytes",
        "full_transcription",
        "unrestricted_transcript",
        "notice_body",
        "source_document_bytes",
    ];
    match value {
        serde_json::Value::Object(fields) => {
            for (key, child) in fields {
                if FORBIDDEN
                    .iter()
                    .any(|forbidden| key.eq_ignore_ascii_case(forbidden))
                {
                    return Err(format!(
                        "document packet contains forbidden raw-evidence field {path}.{key}"
                    ));
                }
                validate_bounded_document_packet_value(child, &format!("{path}.{key}"))?;
            }
        }
        serde_json::Value::Array(items) => {
            for (index, child) in items.iter().enumerate() {
                validate_bounded_document_packet_value(child, &format!("{path}[{index}]"))?;
            }
        }
        _ => {}
    }
    Ok(())
}

fn bounded_packet_projection(packet: &serde_json::Value) -> Result<serde_json::Value, String> {
    validate_bounded_document_packet_value(packet, "packet")?;
    let boundary = packet
        .get("evidence_boundary")
        .and_then(serde_json::Value::as_object)
        .ok_or_else(|| "document packet is missing evidence_boundary object".to_owned())?;
    for flag in [
        "raw_pdf_committed",
        "raw_ocr_committed",
        "page_image_committed",
        "source_document_committed",
        "ocr_dump_committed",
    ] {
        if boundary.get(flag).and_then(serde_json::Value::as_bool) == Some(true) {
            return Err(format!(
                "document packet evidence boundary marks {flag} true"
            ));
        }
    }
    for flag in [
        "source_document_committed",
        "ocr_dump_committed",
        "page_image_committed",
    ] {
        if boundary.get(flag).and_then(serde_json::Value::as_bool) != Some(false) {
            return Err(format!(
                "document packet evidence boundary must explicitly mark {flag} false"
            ));
        }
    }
    let mut projection = serde_json::Map::new();
    for key in [
        "source_id",
        "capture_session_id",
        "capture_config_id",
        "packet_id",
        "visual_packet_id",
        "return_packet_id",
        "release_packet_id",
        "downstream_handoff_id",
        "target_layer",
        "validation_status",
        "release_status",
        "review_status",
        "downstream_status",
    ] {
        if let Some(value) = packet.get(key).filter(|value| !value.is_null()) {
            let text = value
                .as_str()
                .ok_or_else(|| format!("document packet field {key:?} must be a string"))?;
            if text.len() > 512 {
                return Err(format!("document packet field {key:?} exceeds 512 bytes"));
            }
            projection.insert(key.into(), serde_json::Value::String(text.to_owned()));
        }
    }
    for key in [
        "source_id",
        "packet_id",
        "visual_packet_id",
        "return_packet_id",
        "release_packet_id",
        "downstream_handoff_id",
        "target_layer",
        "validation_status",
        "release_status",
        "downstream_status",
    ] {
        if !projection.contains_key(key) {
            return Err(format!("document packet is missing required field {key:?}"));
        }
    }
    if projection
        .get("target_layer")
        .and_then(serde_json::Value::as_str)
        != Some("trans-downstream")
        || projection
            .get("validation_status")
            .and_then(serde_json::Value::as_str)
            != Some("schema_valid")
        || projection
            .get("release_status")
            .and_then(serde_json::Value::as_str)
            != Some("released")
        || projection
            .get("downstream_status")
            .and_then(serde_json::Value::as_str)
            != Some("handoff_ready")
    {
        return Err("document packet is not an approved downstream-ready release handoff".into());
    }
    if projection
        .get("review_status")
        .and_then(serde_json::Value::as_str)
        .is_some_and(|status| status != "qa_approved")
    {
        return Err("document packet review status is not approved".into());
    }
    let approval = packet
        .get("release_approval_ref")
        .and_then(serde_json::Value::as_object)
        .ok_or_else(|| "document packet is missing release_approval_ref".to_owned())?;
    let approval_string = |key: &str| -> Result<&str, String> {
        approval
            .get(key)
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty() && value.len() <= 512)
            .ok_or_else(|| format!("document packet release approval is missing valid {key:?}"))
    };
    if approval_string("schema_version")? != "release-approval-ref/v1"
        || approval_string("approval_status")? != "approved"
        || Some(approval_string("release_packet_id")?)
            != projection
                .get("release_packet_id")
                .and_then(serde_json::Value::as_str)
    {
        return Err("document packet release approval does not match the released handoff".into());
    }
    let trace_packet_id = approval_string("trace_packet_id")?;
    let release_id = approval_string("release_id")?;
    projection.insert(
        "trace_packet_id".into(),
        serde_json::Value::String(trace_packet_id.to_owned()),
    );
    projection.insert(
        "release_id".into(),
        serde_json::Value::String(release_id.to_owned()),
    );
    projection.insert(
        "approval_status".into(),
        serde_json::Value::String("approved".into()),
    );
    if let Some(confidence) = packet
        .get("confidence")
        .and_then(serde_json::Value::as_object)
    {
        if let Some(overall) = confidence.get("overall") {
            let score = overall
                .as_f64()
                .filter(|score| (0.0..=1.0).contains(score))
                .ok_or_else(|| {
                    "document packet confidence.overall must be between 0 and 1".to_owned()
                })?;
            projection.insert("overall_confidence".into(), serde_json::json!(score));
        }
    }
    for key in [
        "field_origin",
        "evidence_boundary",
        "auditable_text_chain_ref",
        "handwriting_index_gate_ref",
        "field_evidence_refs",
        "document_bridge_ref",
        "review_flags",
        "frame_identity",
    ] {
        if let Some(value) = packet.get(key).filter(|value| !value.is_null()) {
            let serialized = serde_json::to_string(value).map_err(|error| error.to_string())?;
            if serialized.len() > 8_192 {
                return Err(format!("document packet {key} exceeds 8192 bytes"));
            }
            projection.insert(key.into(), value.clone());
        }
    }
    projection.insert(
        "destinations".into(),
        packet
            .get("destinations")
            .cloned()
            .unwrap_or_else(|| serde_json::Value::Array(Vec::new())),
    );
    if let Some(destinations) = projection
        .get("destinations")
        .and_then(serde_json::Value::as_array)
    {
        if destinations.is_empty()
            || destinations.len() > 8
            || destinations.iter().any(|destination| {
                !matches!(
                    destination.as_str(),
                    Some("json_export" | "sheets_reporting")
                )
            })
        {
            return Err("document packet destinations are invalid or unsupported".into());
        }
    } else {
        return Err("document packet destinations must be an array".into());
    }
    const REPORTING_FIELDS: &[&str] = &[
        "issuer",
        "notice_type",
        "county",
        "state",
        "event_or_effective_date",
        "pwsid",
        "water_system_name",
        "affected_area",
        "notice_reason_or_trigger",
        "corrective_action_summary",
    ];
    if let Some(fields) = packet
        .get("reporting_row_payload")
        .or_else(|| packet.get("reporting_fields"))
        .and_then(serde_json::Value::as_object)
    {
        let mut bounded = serde_json::Map::new();
        for key in REPORTING_FIELDS {
            if let Some(value) = fields.get(*key).filter(|value| !value.is_null()) {
                let text = match value {
                    serde_json::Value::String(text) => text.clone(),
                    serde_json::Value::Number(_) | serde_json::Value::Bool(_) => value.to_string(),
                    _ => return Err(format!("document reporting field {key:?} must be a scalar")),
                };
                if text.len() > 512 {
                    return Err(format!(
                        "document reporting field {key:?} exceeds 512 bytes"
                    ));
                }
                bounded.insert((*key).into(), serde_json::Value::String(text));
            }
        }
        if !bounded.is_empty() {
            projection.insert(
                "reporting_fields".into(),
                serde_json::Value::Object(bounded),
            );
        }
    }
    for key in ["page_refs", "region_refs"] {
        if let Some(value) = packet.get(key).filter(|value| !value.is_null()) {
            let serialized = serde_json::to_string(value).map_err(|error| error.to_string())?;
            if serialized.len() > 8_192 {
                return Err(format!("document packet {key} exceeds 8192 bytes"));
            }
            projection.insert(key.into(), value.clone());
        }
    }
    let projection = serde_json::Value::Object(projection);
    if serde_json::to_vec(&projection)
        .map_err(|error| error.to_string())?
        .len()
        > 32 * 1024
    {
        return Err("bounded document packet projection exceeds the 32 KiB limit".into());
    }
    Ok(projection)
}

fn document_packets_csv(input_path: &str) -> Result<(Vec<u8>, usize), String> {
    const MAX_INPUT_BYTES: u64 = 10 * 1024 * 1024;
    const MAX_PACKET_LINE_BYTES: usize = 256 * 1024;
    const MAX_PACKETS: usize = 500;
    let metadata =
        fs::metadata(input_path).map_err(|error| format!("cannot inspect packet file: {error}"))?;
    if metadata.len() > MAX_INPUT_BYTES {
        return Err("document packet file exceeds the 10 MiB import limit".into());
    }
    let file =
        fs::File::open(input_path).map_err(|error| format!("cannot read packet file: {error}"))?;
    let mut reader = BufReader::new(file);
    let mut writer = csv::Writer::from_writer(Vec::new());
    writer
        .write_record([
            "record_type",
            "source",
            "source_type",
            "source_external_ids_json",
            "source_attribute:packet_id",
            "source_attribute:visual_packet_id",
            "source_attribute:return_packet_id",
            "source_attribute:release_packet_id",
            "source_attribute:downstream_handoff_id",
            "source_attribute:trace_packet_id",
            "source_attribute:release_id",
            "source_attribute:approval_status",
            "source_attribute:target_layer",
            "source_attribute:validation_status",
            "source_attribute:release_status",
            "source_attribute:review_status",
            "source_attribute:downstream_status",
            "source_attribute:bounded_packet_metadata_json",
        ])
        .map_err(|error| error.to_string())?;
    let mut count = 0;
    let mut total_bytes = 0u64;
    let mut release_packet_ids = HashSet::new();
    let mut downstream_handoff_ids = HashSet::new();
    let mut line = String::new();
    loop {
        line.clear();
        let bytes = reader
            .read_line(&mut line)
            .map_err(|error| format!("cannot read packet line: {error}"))?;
        if bytes == 0 {
            break;
        }
        total_bytes = total_bytes.saturating_add(bytes as u64);
        if total_bytes > MAX_INPUT_BYTES {
            return Err("document packet input exceeds the 10 MiB import limit".into());
        }
        if bytes > MAX_PACKET_LINE_BYTES {
            return Err(format!(
                "document packet line {} exceeds the 256 KiB limit",
                count + 1
            ));
        }
        if line.trim().is_empty() {
            continue;
        }
        if count >= MAX_PACKETS {
            return Err("document packet file exceeds the 500 packet limit".into());
        }
        let packet: serde_json::Value = serde_json::from_str(&line).map_err(|error| {
            format!(
                "invalid JSON on document packet line {}: {error}",
                count + 1
            )
        })?;
        let projection = bounded_packet_projection(&packet)
            .map_err(|error| format!("document packet line {}: {error}", count + 1))?;
        let get = |key: &str| document_packet_value(&projection, key);
        let _source_id = get("source_id")?;
        let packet_id = get("packet_id")?;
        let visual_id = get("visual_packet_id")?;
        let return_id = get("return_packet_id")?;
        let release_id = get("release_packet_id")?;
        let handoff_id = get("downstream_handoff_id")?;
        let trace_id = get("trace_packet_id")?;
        if !release_packet_ids.insert(release_id.clone()) {
            return Err(format!(
                "document packet line {} repeats release_packet_id {release_id:?}",
                count + 1
            ));
        }
        if !downstream_handoff_ids.insert(handoff_id.clone()) {
            return Err(format!(
                "document packet line {} repeats downstream_handoff_id {handoff_id:?}",
                count + 1
            ));
        }
        let validation = get("validation_status")?;
        let release = get("release_status")?;
        let review = projection
            .get("review_status")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("");
        let approval_status = get("approval_status")?;
        let target_layer = get("target_layer")?;
        let downstream = get("downstream_status")?;
        let external_ids = serde_json::to_string(&vec![("trans-release", release_id.as_str())])
            .map_err(|error| error.to_string())?;
        writer
            .write_record([
                "entity",
                &format!("Document packet · {release_id}"),
                "Document evidence packet",
                &external_ids,
                &packet_id,
                &visual_id,
                &return_id,
                &release_id,
                &handoff_id,
                &trace_id,
                &get("release_id")?,
                &approval_status,
                &target_layer,
                &validation,
                &release,
                &review,
                &downstream,
                &serde_json::to_string(&projection).map_err(|error| error.to_string())?,
            ])
            .map_err(|error| error.to_string())?;
        count += 1;
    }
    if count == 0 {
        return Err("document packet file contains no packets".into());
    }
    writer.flush().map_err(|error| error.to_string())?;
    writer
        .into_inner()
        .map(|bytes| (bytes, count))
        .map_err(|error| error.to_string())
}

fn import_document_packets_cli(
    case_path: &str,
    input_path: &str,
    json_output: bool,
) -> Result<(), String> {
    let case_file = Path::new(case_path);
    if paths_refer_to_same_file(case_path, input_path) {
        return Err("document packet input cannot replace the case file".into());
    }
    let _case_lock = lock_automation_case(case_file)?;
    let (csv_bytes, packet_count) = document_packets_csv(input_path)?;
    let temporary_path = write_interchange_csv_temp(csv_bytes, "DOCUMENT-PACKET")?;
    let result =
        (|| {
            let contents = fs::read_to_string(case_file)
                .map_err(|error| format!("cannot read case: {error}"))?;
            let mut case = serde_json::from_str::<CaseFile>(&contents)
                .map_err(|error| format!("cannot parse case: {error}"))?;
            normalize_snapshot_database_paths(&mut case, case_path);
            let mut app = App::automation_context(case, case_path);
            const EVIDENCE_CHART_TITLE: &str = "Document evidence · trans-release";
            let existing_evidence_chart = app
                .case
                .chart_tabs
                .iter()
                .find(|chart| chart.title == EVIDENCE_CHART_TITLE)
                .map(|chart| chart.id);
            if let Some(chart_id) = existing_evidence_chart {
                app.switch_chart(chart_id);
            } else if app.case.active_chart_title != EVIDENCE_CHART_TITLE {
                app.import_into_new_chart = true;
            }
            app.import_path = temporary_path.to_string_lossy().into_owned();
            app.import_column_mapping = infer_import_column_mapping(&[
                "record_type".into(),
                "source".into(),
                "source_type".into(),
                "source_external_ids_json".into(),
            ]);
            app.import_ingest_source_override = Some("trans-release".into());
            app.import_delimited();
            let summary = app
                .status
                .strip_prefix("CSV IMPORT · ")
                .ok_or_else(|| {
                    app.status
                        .strip_prefix("IMPORT FAILED · ")
                        .unwrap_or(&app.status)
                        .to_owned()
                })?
                .to_owned();
            let (created, updated, skipped) = app.delimited_import_counts.ok_or_else(|| {
                "document packet importer did not return record counts".to_owned()
            })?;
            app.case.active_chart_title = EVIDENCE_CHART_TITLE.into();
            save_case_atomically(case_file, &app.case)?;
            if json_output {
                println!("{}", serde_json::to_string_pretty(&serde_json::json!({
                "schema_version": 1, "ok": true, "saved": true, "case": case_path,
                "input": input_path, "chart_id": app.case.active_chart_id,
                "chart_title": app.case.active_chart_title, "packets": packet_count,
                "created": created, "updated": updated, "skipped": skipped, "summary": summary,
            })).map_err(|error| error.to_string())?);
            } else {
                println!(
                    "APPROVED HANDOFF IMPORT · {} handoffs · chart {} · {summary}",
                    packet_count, app.case.active_chart_title
                );
            }
            Ok(())
        })();
    let cleanup = fs::remove_file(&temporary_path);
    if let Err(error) = cleanup {
        if result.is_ok() {
            return Err(format!(
                "import completed, but temporary packet projection could not be removed: {error}"
            ));
        }
    }
    result
}

fn attach_transcription_candidates_cli(
    case_path: &str,
    manifest_path: &str,
    json_output: bool,
) -> Result<(), String> {
    const MAX_MANIFEST_BYTES: u64 = 4 * 1024 * 1024;
    const MAX_CANDIDATE_TEXT_BYTES: u64 = 10 * 1024 * 1024;
    let case_file = Path::new(case_path);
    let manifest_file = Path::new(manifest_path);
    if paths_refer_to_same_file(case_path, manifest_path) {
        return Err("transcription candidate manifest cannot replace the case file".into());
    }
    let manifest_bytes = fs::read(manifest_file)
        .map_err(|error| format!("cannot read transcription candidate manifest: {error}"))?;
    if manifest_bytes.len() as u64 > MAX_MANIFEST_BYTES {
        return Err("transcription candidate manifest exceeds the 4 MiB limit".into());
    }
    let manifest = serde_json::from_slice::<TranscriptionCandidateManifest>(&manifest_bytes)
        .map_err(|error| format!("cannot parse transcription candidate manifest: {error}"))?;
    if manifest.schema != "arch-notebook-transcription-candidate/v1" {
        return Err("unsupported transcription candidate manifest schema".into());
    }
    let valid_sha256 = |value: &str| {
        value.len() == 64
            && value
                .bytes()
                .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
    };
    if !valid_sha256(&manifest.source_sha256) || !valid_sha256(&manifest.output_sha256) {
        return Err("transcription candidate manifest contains an invalid SHA-256 digest".into());
    }
    if manifest.source_file.trim().is_empty()
        || Path::new(&manifest.source_file)
            .file_name()
            .and_then(|name| name.to_str())
            != Some(manifest.source_file.as_str())
    {
        return Err("transcription candidate source_file must be a filename".into());
    }
    if manifest.normalizer != "tran.pdf.plain.build_plain_candidate"
        || manifest.trans_head.len() != 40
        || !manifest
            .trans_head
            .bytes()
            .all(|byte| byte.is_ascii_hexdigit())
        || manifest.ocr_engine.trim().is_empty()
        || !matches!(
            manifest.qwen_analysis_status.as_str(),
            "not_run"
                | "pending_local_model_service"
                | "uncompleted_local_cpu_inference_too_slow"
                | "completed_review_required"
        )
    {
        return Err("transcription candidate processing provenance is incomplete".into());
    }
    if !manifest.human_review_required
        || manifest.page_count == 0
        || manifest.page_count > 5_000
        || manifest.pages.len() != manifest.page_count
    {
        return Err("transcription candidate manifest must retain review-required pages".into());
    }
    for (index, page) in manifest.pages.iter().enumerate() {
        if page.page != index + 1
            || !page.requires_review
            || !valid_sha256(&page.render_sha256)
            || !valid_sha256(&page.normalized_text_sha256)
        {
            return Err(format!(
                "transcription candidate page {} has invalid identity, digest, or review state",
                index + 1
            ));
        }
    }
    let output_name = Path::new(&manifest.output_file);
    if output_name.as_os_str().is_empty()
        || output_name.file_name().and_then(|name| name.to_str()) != output_name.to_str()
    {
        return Err("transcription candidate output_file must be a filename".into());
    }
    let output_path = manifest_file
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
        .unwrap_or_else(|| Path::new("."))
        .join(output_name);
    let output_metadata = fs::metadata(&output_path)
        .map_err(|error| format!("cannot read transcription candidate text: {error}"))?;
    if output_metadata.len() > MAX_CANDIDATE_TEXT_BYTES {
        return Err("transcription candidate text exceeds the 10 MiB limit".into());
    }
    let output_bytes = fs::read(&output_path)
        .map_err(|error| format!("cannot read transcription candidate text: {error}"))?;
    if sha256_hex(&output_bytes) != manifest.output_sha256 {
        return Err("transcription candidate text SHA-256 does not match its manifest".into());
    }

    let _case_lock = lock_automation_case(case_file)?;
    let case_contents =
        fs::read_to_string(case_file).map_err(|error| format!("cannot read case: {error}"))?;
    let mut case = serde_json::from_str::<CaseFile>(&case_contents)
        .map_err(|error| format!("cannot parse case: {error}"))?;
    let mut matched: Vec<(Option<usize>, usize)> = Vec::new();
    for (index, entity) in case.entities.iter().enumerate() {
        if entity_attribute_value(entity, "source_sha256") == Some(manifest.source_sha256.as_str())
            && entity_attribute_value(entity, "source_file") == Some(manifest.source_file.as_str())
        {
            matched.push((None, index));
        }
    }
    for (chart_index, chart) in case.chart_tabs.iter().enumerate() {
        for (entity_index, entity) in chart.entities.iter().enumerate() {
            if entity_attribute_value(entity, "source_sha256")
                == Some(manifest.source_sha256.as_str())
                && entity_attribute_value(entity, "source_file")
                    == Some(manifest.source_file.as_str())
            {
                matched.push((Some(chart_index), entity_index));
            }
        }
    }
    let [(chart_index, entity_index)] = matched.as_slice() else {
        return Err(if matched.is_empty() {
            "case has no source entity matching the PDF filename and SHA-256".into()
        } else {
            "case has multiple source entities matching the PDF filename and SHA-256".into()
        });
    };
    let entity = if let Some(chart_index) = chart_index {
        &mut case.chart_tabs[*chart_index].entities[*entity_index]
    } else {
        &mut case.entities[*entity_index]
    };
    let source_path = entity_attribute_value(entity, "source_path")
        .ok_or_else(|| "matching source entity is missing source_path".to_owned())?;
    let source_bytes = fs::read(source_path)
        .map_err(|error| format!("cannot read source PDF for identity verification: {error}"))?;
    if source_bytes.len() as u64 != manifest.source_bytes
        || sha256_hex(&source_bytes) != manifest.source_sha256
    {
        return Err("source PDF size or SHA-256 does not match the candidate manifest".into());
    }
    let absolute_output_path = output_path
        .canonicalize()
        .map_err(|error| format!("cannot resolve transcription candidate path: {error}"))?;
    let absolute_manifest_path = manifest_file
        .canonicalize()
        .map_err(|error| format!("cannot resolve transcription candidate manifest: {error}"))?;
    let manifest_sha256 = sha256_hex(&manifest_bytes);
    let candidate_page_count = manifest.page_count.to_string();
    let candidate_render_dpi = manifest.ocr_render_dpi.to_string();
    let candidate_output_path = absolute_output_path.to_string_lossy().into_owned();
    let candidate_manifest_path = absolute_manifest_path.to_string_lossy().into_owned();
    for (key, value) in [
        (
            "transcription_candidate_path",
            candidate_output_path.as_str(),
        ),
        (
            "transcription_candidate_sha256",
            manifest.output_sha256.as_str(),
        ),
        (
            "transcription_candidate_manifest_path",
            candidate_manifest_path.as_str(),
        ),
        (
            "transcription_candidate_manifest_sha256",
            manifest_sha256.as_str(),
        ),
        (
            "transcription_candidate_page_count",
            candidate_page_count.as_str(),
        ),
        ("transcription_candidate_status", "review_required"),
        (
            "transcription_candidate_normalizer",
            manifest.normalizer.as_str(),
        ),
        (
            "transcription_candidate_trans_head",
            manifest.trans_head.as_str(),
        ),
        (
            "transcription_candidate_ocr_engine",
            manifest.ocr_engine.as_str(),
        ),
        (
            "transcription_candidate_render_dpi",
            candidate_render_dpi.as_str(),
        ),
        ("transcription_candidate_text_in_case", "false"),
        (
            "qwen_analysis_status",
            manifest.qwen_analysis_status.as_str(),
        ),
    ] {
        set_entity_attribute(entity, key, Some(value));
    }
    let source_entity_id = entity.id;
    let source_entity_name = entity.name.clone();
    let chart_title = (*chart_index)
        .and_then(|index| case.chart_tabs.get(index).map(|chart| chart.title.as_str()))
        .unwrap_or(case.active_chart_title.as_str())
        .to_owned();
    save_case_atomically(case_file, &case)?;
    if json_output {
        println!(
            "{}",
            serde_json::to_string_pretty(&serde_json::json!({
                "schema_version": 1,
                "ok": true,
                "saved": true,
                "case": case_path,
                "manifest": absolute_manifest_path,
                "source_entity_id": source_entity_id,
                "source_entity": source_entity_name,
                "chart_title": chart_title,
                "source_sha256": manifest.source_sha256,
                "candidate_sha256": manifest.output_sha256,
                "pages": manifest.page_count,
                "review_required": true,
                "raw_transcription_imported": false,
                "relationships_created": 0,
            }))
            .map_err(|error| error.to_string())?
        );
    } else {
        println!(
            "TRANSCRIPTION CANDIDATE ATTACHED · {} PAGES · REVIEW REQUIRED · {}",
            manifest.page_count, source_entity_name
        );
    }
    Ok(())
}

fn import_delimited_cli(
    case_path: &str,
    input_path: &str,
    design_selector: Option<&str>,
    chart_selector: Option<&str>,
    new_chart: bool,
    ingest_source_override: Option<&str>,
    json_output: bool,
) -> Result<(), String> {
    if new_chart && chart_selector.is_some() {
        return Err("choose either --chart or --new-chart".into());
    }
    let case_file = Path::new(case_path);
    if paths_refer_to_same_file(case_path, input_path) {
        return Err("delimited input cannot replace the case file".into());
    }
    if ingest_source_override.is_some_and(|source| source.trim().is_empty()) {
        return Err("--source must contain a non-empty provenance key".into());
    }
    let _case_lock = lock_automation_case(case_file)?;
    let contents =
        fs::read_to_string(case_file).map_err(|error| format!("cannot read case: {error}"))?;
    let mut case = serde_json::from_str::<CaseFile>(&contents)
        .map_err(|error| format!("cannot parse case: {error}"))?;
    normalize_snapshot_database_paths(&mut case, case_path);

    let delimiter = detect_import_delimiter(Path::new(input_path))?;
    let mut reader = csv::ReaderBuilder::new()
        .delimiter(delimiter)
        .from_path(input_path)
        .map_err(|error| format!("cannot read delimited import: {error}"))?;
    let headers = normalize_delimited_headers(
        reader
            .headers()
            .map_err(|error| format!("cannot read delimited headers: {error}"))?
            .iter()
            .map(str::to_owned)
            .collect(),
    );
    validate_delimited_headers(headers.iter())?;

    let design = if let Some(selector) = design_selector {
        let matches = case
            .import_specifications
            .iter()
            .filter(|spec| {
                spec.id.to_string().eq_ignore_ascii_case(selector)
                    || spec.name.eq_ignore_ascii_case(selector)
            })
            .collect::<Vec<_>>();
        let [design] = matches.as_slice() else {
            return Err(if matches.is_empty() {
                format!("import design not found: {selector}")
            } else {
                format!("import design selector is ambiguous: {selector}")
            });
        };
        let compatibility_issues = import_design_compatibility_issues(design, &headers);
        if !compatibility_issues.is_empty() {
            return Err(format!(
                "input columns do not satisfy import design {:?}: {}",
                design.name,
                compatibility_issues.join("; ")
            ));
        }
        (*design).clone()
    } else {
        let matches = case
            .import_specifications
            .iter()
            .filter(|spec| import_design_fits_headers(spec, &headers))
            .collect::<Vec<_>>();
        match matches.as_slice() {
            [design] => (*design).clone(),
            [] if case.import_specifications.is_empty() => {
                return Err(
                    "case has no saved import designs; create or import a design before scripted ingestion".into(),
                );
            }
            [] => {
                let closest = case
                    .import_specifications
                    .iter()
                    .map(|spec| (spec, import_design_compatibility_issues(spec, &headers)))
                    .min_by(|(left_spec, left_issues), (right_spec, right_issues)| {
                        left_issues.len().cmp(&right_issues.len()).then_with(|| {
                            left_spec
                                .name
                                .to_ascii_lowercase()
                                .cmp(&right_spec.name.to_ascii_lowercase())
                        })
                    });
                if let Some((spec, issues)) = closest {
                    return Err(format!(
                        "no saved import design matches the input; closest design {:?} needs review: {}",
                        spec.name,
                        issues.join("; ")
                    ));
                }
                return Err("no saved import design matches the input columns".into());
            }
            _ => {
                return Err(format!(
                    "multiple import designs match the input; choose one with --design: {}",
                    matches
                        .iter()
                        .map(|design| design.name.as_str())
                        .collect::<Vec<_>>()
                        .join(", ")
                ));
            }
        }
    };
    let mut mapping = design.mapping.clone();
    remap_import_mapping_headers(&mut mapping, &headers);

    let mut app = App::automation_context(case, case_path);
    if let Some(selector) = chart_selector {
        let chart_id = chart_id_for_selector(&app.case, selector)?;
        app.switch_chart(chart_id);
        if app.case.active_chart_id != chart_id {
            return Err(format!("could not open destination chart: {selector}"));
        }
    }
    app.import_path = input_path.to_owned();
    app.import_column_mapping = mapping;
    app.import_into_new_chart = new_chart;
    app.import_ingest_source_override =
        ingest_source_override.map(|source| source.trim().to_owned());
    app.import_delimited();
    let summary = app
        .status
        .strip_prefix("CSV IMPORT · ")
        .or_else(|| app.status.strip_prefix("TSV IMPORT · "))
        .ok_or_else(|| {
            app.status
                .strip_prefix("IMPORT FAILED · ")
                .unwrap_or(&app.status)
                .to_owned()
        })?
        .to_owned();
    let (created, updated, skipped) = app
        .delimited_import_counts
        .ok_or_else(|| "delimited importer did not return staged record counts".to_owned())?;
    save_case_atomically(case_file, &app.case)?;
    if json_output {
        println!(
            "{}",
            serde_json::to_string_pretty(&serde_json::json!({
                "schema_version": 1,
                "ok": true,
                "saved": true,
                "case": case_path,
                "input": input_path,
                "design_id": design.id,
                "design": design.name,
                "chart_id": app.case.active_chart_id,
                "chart_title": app.case.active_chart_title,
                "created": created,
                "updated": updated,
                "skipped": skipped,
                "summary": summary,
            }))
            .map_err(|error| error.to_string())?
        );
    } else {
        println!(
            "CSV/TSV IMPORT · {} · CHART {} · {summary}",
            design.name, app.case.active_chart_title
        );
    }
    Ok(())
}

fn import_interchange_cli(
    case_path: &str,
    input_path: &str,
    json_output: bool,
    source_format: &str,
    reported_input_path: Option<&str>,
) -> Result<(), String> {
    let case_file = Path::new(case_path);
    let _case_lock = lock_automation_case(case_file)?;
    let content =
        fs::read_to_string(case_file).map_err(|error| format!("cannot read case: {error}"))?;
    let mut case = serde_json::from_str::<CaseFile>(&content)
        .map_err(|error| format!("cannot parse case: {error}"))?;
    normalize_snapshot_database_paths(&mut case, case_path);
    let mut app = App::automation_context(case, case_path);
    app.import_path = input_path.to_owned();
    match source_format {
        "GRAPHML" => app.import_graphml(),
        "KML" => app.import_kml(),
        "ANX" => app.import_anx(),
        _ => return Err(format!("unsupported interchange format {source_format}")),
    }
    if let Some(error) = app
        .status
        .strip_prefix(&format!("{source_format} IMPORT FAILED · "))
    {
        return Err(error.to_owned());
    }
    save_case_atomically(case_file, &app.case)?;
    if json_output {
        println!(
            "{}",
            serde_json::to_string_pretty(&serde_json::json!({
                "schema_version": 1,
                "ok": true,
                "saved": true,
                "case": case_path,
                "input": reported_input_path.unwrap_or(input_path),
                "entities": app.case.entities.len(),
                "relationships": app.case.links.len(),
                "message": app.status,
            }))
            .map_err(|error| error.to_string())?
        );
    } else {
        println!("{}", app.status);
    }
    Ok(())
}

fn read_sqlite_schema(database_path: &str) -> Result<SqliteSchemaInventory, String> {
    let mut connection =
        Connection::open_with_flags(database_path, OpenFlags::SQLITE_OPEN_READ_ONLY)
            .map_err(|error| format!("cannot open SQLite database read-only: {error}"))?;
    enforce_sqlite_query_only(&connection)
        .map_err(|error| format!("cannot enable SQLite query-only mode: {error}"))?;
    connection
        .busy_timeout(Duration::from_secs(5))
        .map_err(|error| error.to_string())?;
    let transaction = connection
        .transaction_with_behavior(TransactionBehavior::Deferred)
        .map_err(|error| error.to_string())?;
    let schema_version = transaction
        .query_row("PRAGMA schema_version", [], |row| row.get(0))
        .map_err(|error| error.to_string())?;
    let (schema_fingerprint, schema_object_fingerprints) =
        sqlite_schema_fingerprint_and_objects(&transaction)
            .map_err(|error| format!("cannot fingerprint SQLite schema: {error}"))?;
    let objects = {
        let mut statement = transaction
            .prepare(
                "SELECT type, name, sql FROM sqlite_schema \
                 WHERE type IN ('table', 'view') AND substr(name, 1, 7) <> 'sqlite_' \
                 ORDER BY type, name",
            )
            .map_err(|error| error.to_string())?;
        statement
            .query_map([], |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, Option<String>>(2)?,
                ))
            })
            .map_err(|error| error.to_string())?
            .collect::<rusqlite::Result<Vec<_>>>()
            .map_err(|error| error.to_string())?
    };
    let mut schema = Vec::with_capacity(objects.len());
    for (object_type, name, definition) in objects {
        let (columns, inspection_error) = if object_type == "view" {
            let query = format!("SELECT * FROM {} LIMIT 0", quote_sql_identifier(&name));
            match transaction.prepare(&query) {
                Ok(statement) => (
                    statement
                        .column_names()
                        .map(|column| {
                            serde_json::json!({
                                "name": column,
                                "type": "",
                                "not_null": false,
                                "primary_key_order": 0,
                            })
                        })
                        .collect::<Vec<_>>(),
                    None,
                ),
                Err(error) => (Vec::new(), Some(error.to_string())),
            }
        } else {
            let pragma = format!("PRAGMA table_xinfo({})", quote_sql_identifier(&name));
            let mut statement = transaction
                .prepare(&pragma)
                .map_err(|error| error.to_string())?;
            let columns = statement
                .query_map([], |row| {
                    Ok(serde_json::json!({
                        "name": row.get::<_, String>(1)?,
                        "type": row.get::<_, String>(2)?,
                        "not_null": row.get::<_, bool>(3)?,
                        "primary_key_order": row.get::<_, i64>(5)?,
                        "hidden": row.get::<_, i64>(6)?,
                    }))
                })
                .map_err(|error| error.to_string())?
                .collect::<rusqlite::Result<Vec<_>>>()
                .map_err(|error| error.to_string())?;
            (columns, None)
        };
        let foreign_key_pragma =
            format!("PRAGMA foreign_key_list({})", quote_sql_identifier(&name));
        let mut statement = transaction
            .prepare(&foreign_key_pragma)
            .map_err(|error| error.to_string())?;
        let foreign_keys = statement
            .query_map([], |row| {
                Ok(serde_json::json!({
                    "id": row.get::<_, i64>(0)?,
                    "sequence": row.get::<_, i64>(1)?,
                    "table": row.get::<_, String>(2)?,
                    "from": row.get::<_, String>(3)?,
                    "to": row.get::<_, Option<String>>(4)?,
                    "on_update": row.get::<_, String>(5)?,
                    "on_delete": row.get::<_, String>(6)?,
                    "match": row.get::<_, String>(7)?,
                }))
            })
            .map_err(|error| error.to_string())?
            .collect::<rusqlite::Result<Vec<_>>>()
            .map_err(|error| error.to_string())?;
        let indexes = if object_type == "table" {
            let index_list_pragma = format!("PRAGMA index_list({})", quote_sql_identifier(&name));
            let index_specs = {
                let mut statement = transaction
                    .prepare(&index_list_pragma)
                    .map_err(|error| error.to_string())?;
                statement
                    .query_map([], |row| {
                        Ok((
                            row.get::<_, i64>(0)?,
                            row.get::<_, String>(1)?,
                            row.get::<_, bool>(2)?,
                            row.get::<_, String>(3)?,
                            row.get::<_, bool>(4)?,
                        ))
                    })
                    .map_err(|error| error.to_string())?
                    .collect::<rusqlite::Result<Vec<_>>>()
                    .map_err(|error| error.to_string())?
            };
            let mut indexes = Vec::with_capacity(index_specs.len());
            for (sequence, index_name, unique, origin, partial) in index_specs {
                let index_info_pragma =
                    format!("PRAGMA index_xinfo({})", quote_sql_identifier(&index_name));
                let mut statement = transaction
                    .prepare(&index_info_pragma)
                    .map_err(|error| error.to_string())?;
                let columns = statement
                    .query_map([], |row| {
                        Ok(serde_json::json!({
                            "sequence": row.get::<_, i64>(0)?,
                            "column_id": row.get::<_, i64>(1)?,
                            "name": row.get::<_, Option<String>>(2)?,
                            "descending": row.get::<_, bool>(3)?,
                            "collation": row.get::<_, Option<String>>(4)?,
                            "key": row.get::<_, bool>(5)?,
                        }))
                    })
                    .map_err(|error| error.to_string())?
                    .collect::<rusqlite::Result<Vec<_>>>()
                    .map_err(|error| error.to_string())?;
                let definition = transaction
                    .query_row(
                        "SELECT sql FROM sqlite_schema WHERE type = 'index' AND name = ?1",
                        [&index_name],
                        |row| row.get::<_, Option<String>>(0),
                    )
                    .optional()
                    .map_err(|error| error.to_string())?
                    .flatten();
                indexes.push(serde_json::json!({
                    "sequence": sequence,
                    "name": index_name,
                    "unique": unique,
                    "origin": origin,
                    "partial": partial,
                    "columns": columns,
                    "definition": definition,
                }));
            }
            indexes
        } else {
            Vec::new()
        };
        let mut object = serde_json::json!({
            "type": object_type,
            "name": name,
            "definition": definition,
            "columns": columns,
            "foreign_keys": foreign_keys,
            "indexes": indexes,
        });
        if let Some(error) = inspection_error {
            object["inspection_error"] = serde_json::json!(error);
        }
        schema.push(object);
    }
    transaction.commit().map_err(|error| error.to_string())?;
    Ok(SqliteSchemaInventory {
        objects: schema,
        schema_version,
        schema_fingerprint: schema_fingerprint.clone(),
        schema_object_fingerprints,
    })
}

fn quote_sql_identifier(identifier: &str) -> String {
    format!("\"{}\"", identifier.replace('"', "\"\""))
}

fn quote_sql_string_literal(value: &str) -> String {
    format!("'{}'", value.replace('\'', "''"))
}

fn sqlite_scoped_identity_expression(namespace: &str, components: &[String]) -> Option<String> {
    if components.is_empty() {
        return None;
    }
    let null_check = components
        .iter()
        .map(|component| format!("{component} IS NULL"))
        .collect::<Vec<_>>()
        .join(" OR ");
    let encoded = components
        .iter()
        .map(|component| {
            format!("typeof({component}) || ':' || coalesce(hex(CAST({component} AS BLOB)), '')")
        })
        .collect::<Vec<_>>()
        .join(" || '|' || ");
    Some(format!(
        "CASE WHEN {null_check} THEN NULL ELSE {} || ':' || ({encoded}) END",
        quote_sql_string_literal(namespace)
    ))
}

fn schema_column<'a>(object: &'a serde_json::Value, aliases: &[&str]) -> Option<&'a str> {
    let columns = object["columns"].as_array()?;
    aliases.iter().find_map(|alias| {
        columns.iter().find_map(|column| {
            let name = column["name"].as_str()?;
            name.trim().eq_ignore_ascii_case(alias).then_some(name)
        })
    })
}

fn schema_prefixed_attribute<'a>(name: &'a str, prefixes: &[&str]) -> Option<&'a str> {
    prefixes.iter().find_map(|prefix| {
        name.get(..prefix.len())
            .filter(|value| value.eq_ignore_ascii_case(prefix))
            .and_then(|_| name.get(prefix.len()..))
            .filter(|attribute| !attribute.trim().is_empty())
    })
}

fn schema_prefixed_attribute_alias(
    name: &str,
    prefixes: &[(&str, &str)],
) -> Option<(String, String)> {
    prefixes.iter().find_map(|(prefix, alias_prefix)| {
        name.get(..prefix.len())
            .filter(|value| value.eq_ignore_ascii_case(prefix))
            .and_then(|_| name.get(prefix.len()..))
            .filter(|attribute| !attribute.trim().is_empty())
            .map(|attribute| ((*alias_prefix).to_owned(), attribute.to_owned()))
    })
}

fn schema_coordinate_column<'a>(
    object: &'a serde_json::Value,
    aliases: &[&str],
) -> Option<&'a str> {
    let columns = object["columns"].as_array()?;
    let mut matching_columns = columns.iter().filter_map(|column| {
        let name = column["name"].as_str()?;
        aliases
            .iter()
            .any(|alias| name.trim().eq_ignore_ascii_case(alias))
            .then_some(name)
    });
    let column = matching_columns.next()?;
    matching_columns.next().is_none().then_some(column)
}

fn sqlite_primary_key_columns(object: &serde_json::Value) -> Vec<&str> {
    let mut columns = object["columns"]
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(|column| {
            Some((
                column["primary_key_order"].as_i64()?,
                column["name"].as_str()?,
            ))
        })
        .filter(|(order, _)| *order > 0)
        .collect::<Vec<_>>();
    columns.sort_by_key(|(order, _)| *order);
    columns.into_iter().map(|(_, name)| name).collect()
}

fn sqlite_unique_key_columns(object: &serde_json::Value) -> Option<Vec<&str>> {
    let primary_key = sqlite_primary_key_columns(object);
    if !primary_key.is_empty() {
        return Some(primary_key);
    }
    let mut candidates = object["indexes"]
        .as_array()?
        .iter()
        .filter(|index| {
            index["unique"].as_bool() == Some(true) && index["partial"].as_bool() != Some(true)
        })
        .filter_map(|index| {
            let columns = index["columns"].as_array()?;
            let key_columns = columns
                .iter()
                .filter(|column| column["key"].as_bool() != Some(false))
                .map(|column| column["name"].as_str())
                .collect::<Option<Vec<_>>>()?;
            (!key_columns.is_empty()).then_some(key_columns)
        })
        .collect::<Vec<_>>();
    candidates.sort_by(|left, right| {
        left.len().cmp(&right.len()).then_with(|| {
            left.iter()
                .map(|column| column.to_ascii_lowercase())
                .cmp(right.iter().map(|column| column.to_ascii_lowercase()))
                .then_with(|| left.cmp(right))
        })
    });
    candidates.into_iter().next()
}

fn sqlite_column_is_unique(object: &serde_json::Value, name: &str) -> bool {
    let primary_key = sqlite_primary_key_columns(object);
    (primary_key.len() == 1 && primary_key[0].eq_ignore_ascii_case(name))
        || object["indexes"]
            .as_array()
            .into_iter()
            .flatten()
            .any(|index| {
                index["unique"].as_bool() == Some(true)
                    && index["partial"].as_bool() != Some(true)
                    && index["columns"].as_array().is_some_and(|columns| {
                        let key_columns = columns
                            .iter()
                            .filter(|column| column["key"].as_bool() != Some(false))
                            .collect::<Vec<_>>();
                        key_columns.len() == 1
                            && key_columns[0]["name"]
                                .as_str()
                                .is_some_and(|column_name| column_name.eq_ignore_ascii_case(name))
                    })
            })
}

fn sqlite_display_expression(object: &serde_json::Value, table_alias: &str) -> Option<String> {
    let display_aliases = [
        "name",
        "entity_name",
        "person_name",
        "organization_name",
        "display_name",
        "display",
        "full_name",
        "label",
        "title",
        "username",
        "user_name",
        "account_name",
        "owner_name",
        "screen_name",
        "handle",
        "email",
        "email_address",
        "subject",
        "caption",
        "value",
    ];
    let table_alias = quote_sql_identifier(table_alias);
    if let Some(column) = schema_column(object, &display_aliases) {
        return Some(format!("{table_alias}.{}", quote_sql_identifier(column)));
    }
    let first_name = schema_column(object, &["first_name", "given_name"])?;
    let last_name = schema_column(object, &["last_name", "family_name"])?;
    Some(format!(
        "trim(coalesce({table_alias}.{first_name}, '') || ' ' || coalesce({table_alias}.{last_name}, ''))",
        first_name = quote_sql_identifier(first_name),
        last_name = quote_sql_identifier(last_name),
    ))
}

fn sqlite_inferred_endpoint(
    link_object: &serde_json::Value,
    schema: &[serde_json::Value],
    id_column: &str,
    join_alias: &str,
) -> Option<(String, String, Option<String>, Option<String>, String)> {
    let link_name = link_object["name"].as_str()?;
    let mut candidates = Vec::new();
    for object in schema {
        let Some(table_name) = object["name"].as_str() else {
            continue;
        };
        if table_name.eq_ignore_ascii_case(link_name) {
            continue;
        }
        let Some(columns) = object["columns"].as_array() else {
            continue;
        };
        let primary_keys: Vec<&str> = columns
            .iter()
            .filter(|column| column["primary_key_order"].as_i64().unwrap_or_default() > 0)
            .filter_map(|column| column["name"].as_str())
            .collect();
        if primary_keys.len() != 1 {
            continue;
        }
        let key_column = primary_keys[0];
        if sqlite_display_expression(object, "entity_candidate").is_none() {
            continue;
        }
        let normalized_table_name = table_name.trim().to_ascii_lowercase();
        let priority = match normalized_table_name.as_str() {
            "entity" | "entities" | "node" | "nodes" => 2,
            "person" | "persons" | "people" | "organization" | "organizations" => 1,
            _ => 0,
        };
        candidates.push((priority, table_name, key_column, object));
    }
    let best_priority = candidates.iter().map(|candidate| candidate.0).max()?;
    let mut best: Vec<_> = candidates
        .into_iter()
        .filter(|candidate| candidate.0 == best_priority)
        .collect();
    if best.len() != 1 {
        return None;
    }
    let (_, table_name, key_column, object) = best.pop()?;
    let link_alias = quote_sql_identifier("link_row");
    let entity_alias = quote_sql_identifier(join_alias);
    let join = format!(
        "LEFT JOIN {} AS {entity_alias} ON {entity_alias}.{} = {link_alias}.{}",
        quote_sql_identifier(table_name),
        quote_sql_identifier(key_column),
        quote_sql_identifier(id_column),
    );
    let expression = sqlite_display_expression(object, join_alias)?;
    let type_expression = schema_column(object, &["entity_type", "type", "kind"])
        .map(|column| format!("{entity_alias}.{}", quote_sql_identifier(column)));
    let representation_expression = schema_column(
        object,
        &[
            "entity_representation",
            "representation",
            "display_representation",
        ],
    )
    .map(|column| format!("{entity_alias}.{}", quote_sql_identifier(column)));
    let identity_expression = sqlite_scoped_identity_expression(
        table_name,
        &[format!("{link_alias}.{}", quote_sql_identifier(id_column))],
    )?;
    Some((
        expression,
        join,
        type_expression,
        representation_expression,
        identity_expression,
    ))
}

fn sqlite_foreign_key_for_column<'a>(
    link_object: &'a serde_json::Value,
    column: &str,
) -> Option<&'a serde_json::Value> {
    sqlite_foreign_key_group_for_column(link_object, column)?
        .into_iter()
        .next()
}

fn sqlite_foreign_key_group_for_column<'a>(
    link_object: &'a serde_json::Value,
    column: &str,
) -> Option<Vec<&'a serde_json::Value>> {
    let foreign_keys = link_object["foreign_keys"].as_array()?;
    let mut matching_groups = foreign_keys
        .iter()
        .filter(|key| {
            key["from"]
                .as_str()
                .is_some_and(|name| name.eq_ignore_ascii_case(column))
        })
        .filter_map(|key| key["id"].as_i64())
        .collect::<Vec<_>>();
    matching_groups.sort_unstable();
    matching_groups.dedup();
    if matching_groups.len() != 1 {
        return None;
    }
    let foreign_key_id = matching_groups[0];
    let mut group = foreign_keys
        .iter()
        .filter(|key| key["id"].as_i64() == Some(foreign_key_id))
        .collect::<Vec<_>>();
    group.sort_by_key(|key| key["sequence"].as_i64().unwrap_or_default());
    (!group.is_empty()).then_some(group)
}

fn sqlite_declared_endpoint(
    link_object: &serde_json::Value,
    schema: &[serde_json::Value],
    link_column: &str,
    join_alias: &str,
) -> Option<(String, String, Option<String>, Option<String>, String)> {
    let foreign_key_group = sqlite_foreign_key_group_for_column(link_object, link_column)?;
    let foreign_key = *foreign_key_group.first()?;
    let target_table = foreign_key["table"].as_str()?;
    if foreign_key_group.iter().any(|key| {
        key["table"]
            .as_str()
            .is_none_or(|table| !table.eq_ignore_ascii_case(target_table))
    }) {
        return None;
    }
    let target_object = schema.iter().find(|object| {
        object["name"]
            .as_str()
            .is_some_and(|name| name.eq_ignore_ascii_case(target_table))
    })?;
    let declared_target_keys = foreign_key_group
        .iter()
        .map(|key| key["to"].as_str().filter(|column| !column.is_empty()))
        .collect::<Vec<_>>();
    let target_keys = if declared_target_keys.iter().all(Option::is_none) {
        let mut primary_keys = target_object["columns"]
            .as_array()?
            .iter()
            .filter(|column| column["primary_key_order"].as_i64().unwrap_or_default() > 0)
            .filter_map(|column| {
                Some((
                    column["primary_key_order"].as_i64()?,
                    column["name"].as_str()?,
                ))
            })
            .collect::<Vec<_>>();
        primary_keys.sort_by_key(|(order, _)| *order);
        primary_keys
            .into_iter()
            .map(|(_, name)| name)
            .collect::<Vec<_>>()
    } else if declared_target_keys.iter().all(Option::is_some) {
        declared_target_keys.into_iter().flatten().collect()
    } else {
        return None;
    };
    if target_keys.len() != foreign_key_group.len() {
        return None;
    }
    let link_alias = quote_sql_identifier("link_row");
    let entity_alias = quote_sql_identifier(join_alias);
    let join_conditions = foreign_key_group
        .iter()
        .zip(&target_keys)
        .map(|(foreign_key, target_key)| {
            let source_key = foreign_key["from"].as_str()?;
            Some(format!(
                "{entity_alias}.{} = {link_alias}.{}",
                quote_sql_identifier(target_key),
                quote_sql_identifier(source_key),
            ))
        })
        .collect::<Option<Vec<_>>>()?;
    let join = format!(
        "LEFT JOIN {} AS {entity_alias} ON {}",
        quote_sql_identifier(target_table),
        join_conditions.join(" AND "),
    );
    let type_expression = schema_column(target_object, &["entity_type", "type", "kind"])
        .map(|column| format!("{entity_alias}.{}", quote_sql_identifier(column)));
    let representation_expression = schema_column(
        target_object,
        &[
            "entity_representation",
            "representation",
            "display_representation",
        ],
    )
    .map(|column| format!("{entity_alias}.{}", quote_sql_identifier(column)));
    let identity_components = foreign_key_group
        .iter()
        .map(|key| {
            let column = key["from"].as_str()?;
            Some(format!("{link_alias}.{}", quote_sql_identifier(column)))
        })
        .collect::<Option<Vec<_>>>()?;
    let identity_expression =
        sqlite_scoped_identity_expression(target_table, &identity_components)?;
    let expression = sqlite_display_expression(target_object, join_alias)
        .unwrap_or_else(|| identity_expression.clone());
    Some((
        expression,
        join,
        type_expression,
        representation_expression,
        identity_expression,
    ))
}

fn sqlite_joined_entity_attribute_projections(
    schema: &[serde_json::Value],
    join_alias: &str,
    side: &str,
    endpoint_join: Option<&str>,
) -> Vec<String> {
    let Some(endpoint_join) = endpoint_join else {
        return Vec::new();
    };
    // Resolve the target from the actual join so projections never reference an absent alias.
    let Some(target_object) = schema.iter().find(|object| {
        object["name"].as_str().is_some_and(|name| {
            let join_prefix = format!(
                "LEFT JOIN {} AS {} ON ",
                quote_sql_identifier(name),
                quote_sql_identifier(join_alias),
            );
            endpoint_join
                .get(..join_prefix.len())
                .is_some_and(|prefix| prefix.eq_ignore_ascii_case(&join_prefix))
        })
    }) else {
        return Vec::new();
    };
    let Some(columns) = target_object["columns"].as_array() else {
        return Vec::new();
    };
    let prefixes = ["entity_attribute_", "attribute_", "property_"];
    let mut attributes = HashSet::new();
    let mut prefixed_attribute_columns = Vec::<(String, String)>::new();
    let mut prefixed_attribute_counts = HashMap::<String, usize>::new();
    for column in columns {
        let Some(name) = column["name"].as_str() else {
            continue;
        };
        if let Some(attribute) = schema_prefixed_attribute(name, &prefixes) {
            *prefixed_attribute_counts
                .entry(attribute.to_ascii_lowercase())
                .or_default() += 1;
            prefixed_attribute_columns.push((name.to_owned(), attribute.to_owned()));
        }
    }
    let mut projections = Vec::new();
    for (attribute, aliases) in [
        ("latitude", &["latitude", "lat", "geo:lat"][..]),
        (
            "longitude",
            &["longitude", "lon", "lng", "long", "geo:lon"][..],
        ),
    ] {
        if prefixed_attribute_counts
            .get(attribute)
            .copied()
            .unwrap_or_default()
            == 0
            && let Some(name) = schema_coordinate_column(target_object, aliases)
        {
            attributes.insert(attribute.to_owned());
            projections.push(format!(
                "\"{join_alias}\".{} AS {}",
                quote_sql_identifier(name),
                quote_sql_identifier(&format!("{side}_attribute:{attribute}")),
            ));
        }
    }
    projections.extend(
        prefixed_attribute_columns
            .into_iter()
            .filter_map(|(name, attribute)| {
                if prefixed_attribute_counts
                    .get(&attribute.to_ascii_lowercase())
                    .copied()
                    != Some(1)
                    || !attributes.insert(attribute.to_ascii_lowercase())
                {
                    return None;
                }
                Some(format!(
                    "\"{join_alias}\".{} AS {}",
                    quote_sql_identifier(&name),
                    quote_sql_identifier(&format!("{side}_attribute:{attribute}")),
                ))
            }),
    );
    projections
}

fn sqlite_endpoint_expression(
    link_object: &serde_json::Value,
    schema: &[serde_json::Value],
    direct_aliases: &[&str],
    id_aliases: &[&str],
    join_alias: &str,
) -> Option<(
    String,
    Option<String>,
    Option<String>,
    Option<String>,
    Option<String>,
)> {
    let link_alias = quote_sql_identifier("link_row");
    if let Some(column) = schema_column(link_object, direct_aliases) {
        let direct_expression = format!("{link_alias}.{}", quote_sql_identifier(column));
        if sqlite_foreign_key_for_column(link_object, column).is_some() {
            if let Some((
                expression,
                join,
                type_expression,
                representation_expression,
                identity_expression,
            )) = sqlite_declared_endpoint(link_object, schema, column, join_alias)
            {
                return Some((
                    expression,
                    Some(join),
                    type_expression,
                    representation_expression,
                    Some(identity_expression),
                ));
            }
            return Some((
                direct_expression.clone(),
                None,
                None,
                None,
                Some(direct_expression),
            ));
        }
        let identity_column = schema_column(link_object, id_aliases).filter(|id| {
            !id.eq_ignore_ascii_case("source_id")
                || sqlite_foreign_key_for_column(link_object, id).is_some()
        });
        if let Some(id_column) = identity_column
            && sqlite_foreign_key_for_column(link_object, id_column).is_some()
            && let Some((_, join, type_expression, representation_expression, identity_expression)) =
                sqlite_declared_endpoint(link_object, schema, id_column, join_alias)
        {
            return Some((
                direct_expression,
                Some(join),
                type_expression,
                representation_expression,
                Some(identity_expression),
            ));
        }
        let identity_expression =
            identity_column.map(|id| format!("{link_alias}.{}", quote_sql_identifier(id)));
        return Some((direct_expression, None, None, None, identity_expression));
    }
    let id_column = schema_column(link_object, id_aliases)?;
    let raw_expression = format!("{link_alias}.{}", quote_sql_identifier(id_column));
    let raw_endpoint = || {
        Some((
            raw_expression.clone(),
            None,
            None,
            None,
            Some(raw_expression.clone()),
        ))
    };
    if sqlite_foreign_key_for_column(link_object, id_column).is_some() {
        if let Some((
            expression,
            join,
            type_expression,
            representation_expression,
            identity_expression,
        )) = sqlite_declared_endpoint(link_object, schema, id_column, join_alias)
        {
            return Some((
                expression,
                Some(join),
                type_expression,
                representation_expression,
                Some(identity_expression),
            ));
        }
        return raw_endpoint();
    }
    let foreign_keys = link_object["foreign_keys"].as_array();
    if foreign_keys.is_none_or(|keys| {
        keys.iter().all(|key| {
            key["from"]
                .as_str()
                .is_none_or(|column| !column.eq_ignore_ascii_case(id_column))
        })
    }) && let Some((
        expression,
        join,
        type_expression,
        representation_expression,
        identity_expression,
    )) = sqlite_inferred_endpoint(link_object, schema, id_column, join_alias)
    {
        return Some((
            expression,
            Some(join),
            type_expression,
            representation_expression,
            Some(identity_expression),
        ));
    }
    raw_endpoint()
}

fn sqlite_query_projection(query: &str, alias: &str) -> Option<String> {
    let suffix = format!(" AS \"{alias}\"");
    query.lines().find_map(|line| {
        let line = line.trim().trim_end_matches(',');
        let expression = line.strip_suffix(&suffix)?.trim();
        let expression = expression.strip_prefix("SELECT ").unwrap_or(expression);
        Some(expression.to_owned())
    })
}

fn sqlite_query_attribute_projections(query: &str) -> Vec<(String, String)> {
    let prefixes = [
        "source_attribute:",
        "target_attribute:",
        "connection_attribute:",
    ];
    let mut projections = Vec::new();
    for line in query.lines() {
        let line = line.trim().trim_end_matches(',');
        let lowercase_line = line.to_ascii_lowercase();
        for prefix in prefixes {
            let marker = format!(" as \"{prefix}");
            let Some(marker_position) = lowercase_line.rfind(&marker) else {
                continue;
            };
            let alias_start = marker_position + marker.len();
            let Some(alias_length) = line[alias_start..].find('"') else {
                continue;
            };
            let attribute = &line[alias_start..alias_start + alias_length];
            if attribute.trim().is_empty() {
                continue;
            }
            projections.push((
                format!("{prefix}{attribute}"),
                line[..marker_position].trim().to_owned(),
            ));
            break;
        }
    }
    projections.sort_by(|left, right| {
        left.0
            .to_ascii_lowercase()
            .cmp(&right.0.to_ascii_lowercase())
            .then_with(|| left.0.cmp(&right.0))
    });
    projections
}

