    #[test]
    fn schedule_status_summary_distinguishes_dispatch_times_and_unavailable_values() {
        assert_eq!(
            super::schedule_dispatch_summary_from_status(
                "Last timer dispatch: Sat 2026-11-28 02:00:00 EST\nNext timer dispatch: Sat 2026-11-28 04:00:00 EST\nArch Notebook SQL schedule for /tmp/case.json: hourly; active and enabled.\n"
            ),
            Some((
                "active and enabled".into(),
                "Sat 2026-11-28 02:00:00 EST".into(),
                "Sat 2026-11-28 04:00:00 EST".into(),
            ))
        );
        assert_eq!(
            super::schedule_dispatch_summary_from_status(
                "Timer dispatch timing: unavailable\nLast timer dispatch: not recorded\nNext timer dispatch: not scheduled\nArch Notebook SQL schedule for /tmp/case.json: hourly; configured; systemd user manager status unavailable.\n"
            ),
            Some((
                "configured; systemd user manager status unavailable".into(),
                "not recorded".into(),
                "not scheduled".into(),
            ))
        );
        assert_eq!(
            super::schedule_dispatch_summary_from_status(
                "Legacy Arch Notebook SQL schedule: daily; configured but not active or enabled.\n"
            ),
            Some((
                "configured but not active or enabled".into(),
                "not recorded".into(),
                "not scheduled".into(),
            ))
        );
        assert_eq!(
            super::schedule_dispatch_summary_from_status("SQL PREFLIGHT PASSED"),
            None
        );
    }

    #[test]
    fn sql_seed_binding_updates_only_the_one_off_parameter_value() {
        let parameters = super::bind_sql_seed_parameter(
            "snapshot_id=baseline\nseed_entity_id=text:old-id",
            "seed_entity_id",
            "source id=42",
        )
        .expect("selected SQL identity binds as text");
        assert_eq!(
            super::parse_sql_parameters(&parameters).expect("bound parameters parse"),
            vec![
                ("snapshot_id".into(), "baseline".into()),
                ("seed_entity_id".into(), "text:source id=42".into())
            ]
        );
        assert_eq!(
            super::bind_sql_seed_parameter("snapshot_id=baseline", "seed_entity_id", "one"),
            Ok("snapshot_id=baseline\nseed_entity_id=text:one".into())
        );
        assert!(super::bind_sql_seed_parameter("bad line", "seed_entity_id", "one").is_err());
        assert!(super::bind_sql_seed_parameter("", "bad-name", "one").is_err());
        assert!(super::bind_sql_seed_parameter("", "seed_entity_id", "two\nlines").is_err());
    }

    #[test]
    fn saved_sql_search_keeps_defaults_but_never_persists_bound_chart_seed_values() {
        let id = Uuid::from_u128(77);
        let search = super::saved_sql_search_from_draft(
            id,
            "  Counterparty lookup  ",
            "/tmp/accounts.sqlite",
            "seed review",
            "SELECT source, target FROM records WHERE owner_id = :seed_entity_id AND state = :state",
            "seed_entity_id=text:previous-chart-id\nstate=text:open\nminimum=int:2",
            Some("seed_entity_id"),
        )
        .expect("valid saved SQL search draft");
        assert_eq!(search.id, id);
        assert_eq!(search.name, "Counterparty lookup");
        assert_eq!(search.database_path, "/tmp/accounts.sqlite");
        assert_eq!(search.series, "seed review");
        assert_eq!(
            search.seed_parameter_name.as_deref(),
            Some("seed_entity_id")
        );
        assert_eq!(
            search.parameters,
            vec![
                ("state".into(), "text:open".into()),
                ("minimum".into(), "int:2".into())
            ]
        );

        let legacy_case: CaseFile =
            serde_json::from_str(include_str!("../fixtures/chart/correctness.case.json"))
                .expect("legacy case without saved searches remains readable");
        assert!(legacy_case.saved_sql_searches.is_empty());
        let mut upgraded_case = legacy_case;
        upgraded_case.saved_sql_searches.push(search);
        let encoded = serde_json::to_string(&upgraded_case).expect("case with search serializes");
        let decoded: CaseFile = serde_json::from_str(&encoded).expect("saved search round trips");
        assert_eq!(decoded.saved_sql_searches.len(), 1);
        assert_eq!(decoded.saved_sql_searches[0].name, "Counterparty lookup");
        assert_eq!(
            decoded.saved_sql_searches[0].parameters,
            vec![
                ("state".into(), "text:open".into()),
                ("minimum".into(), "int:2".into())
            ]
        );
    }

    #[test]
    fn saved_sql_search_package_round_trips_rebased_path_without_case_data() {
        let root = std::env::temp_dir().join(format!(
            "arch-notebook-sql-search-package-{}",
            Uuid::new_v4()
        ));
        std::fs::create_dir_all(&root).expect("create package test directory");
        let case_path = root.join("investigation.case.json");
        let search = super::SavedSqlSearch {
            id: Uuid::from_u128(8101),
            name: "Seeded contacts".into(),
            database_path: "sources/contacts.sqlite".into(),
            series: "contact review".into(),
            query:
                "SELECT source, target FROM contacts WHERE owner_id = :entity_id AND state = :state"
                    .into(),
            parameters: vec![("state".into(), "text:active".into())],
            seed_parameter_name: Some("entity_id".into()),
        };
        let package = super::saved_sql_search_package(&search, &case_path.to_string_lossy());
        assert_eq!(package.schema_version, 1);
        assert_eq!(package.format, "arch-notebook-sql-search");
        assert_eq!(
            package.database_base_path.as_deref(),
            Some(root.to_string_lossy().as_ref())
        );
        assert_eq!(package.search.parameters, search.parameters);
        assert_eq!(
            package.search.seed_parameter_name,
            search.seed_parameter_name
        );

        let package_path = root.join("search.json");
        let contents = serde_json::to_vec(&package).expect("serialize package");
        std::fs::write(&package_path, &contents).expect("write package fixture");
        let decoded = super::read_saved_sql_search_package(&package_path.to_string_lossy())
            .expect("read valid package");
        let imported = super::saved_sql_search_from_package(
            decoded.search,
            decoded.database_base_path.as_deref(),
            None,
            None,
            None,
        )
        .expect("rebase and validate imported search");
        assert_ne!(imported.id, search.id);
        assert_eq!(
            imported.database_path,
            root.join("sources/contacts.sqlite").to_string_lossy()
        );
        assert_eq!(imported.name, search.name);
        assert_eq!(imported.series, search.series);
        assert_eq!(imported.query, search.query);
        assert_eq!(imported.parameters, search.parameters);
        assert_eq!(imported.seed_parameter_name, search.seed_parameter_name);
        assert!(
            !String::from_utf8(contents)
                .expect("JSON is UTF-8")
                .contains("previous-chart-id")
        );
        std::fs::remove_dir_all(root).expect("remove package test directory");
    }

    #[test]
    fn saved_sql_search_package_rejects_bound_seed_values_and_source_overwrite() {
        let root = std::env::temp_dir().join(format!(
            "arch-notebook-sql-search-package-safety-{}",
            Uuid::new_v4()
        ));
        std::fs::create_dir_all(&root).expect("create package test directory");
        let package_path = root.join("bound.json");
        let package = super::SavedSqlSearchPackage {
            format: "arch-notebook-sql-search".into(),
            schema_version: 1,
            database_base_path: None,
            search: super::SavedSqlSearchPackageDefinition {
                name: "Seeded contacts".into(),
                database_path: "contacts.sqlite".into(),
                series: "review".into(),
                query: "SELECT source, target FROM contacts WHERE owner_id = :entity_id".into(),
                parameters: vec![("entity_id".into(), "text:previous-chart-id".into())],
                seed_parameter_name: Some("entity_id".into()),
            },
        };
        std::fs::write(
            &package_path,
            serde_json::to_vec(&package).expect("serialize bound package"),
        )
        .expect("write bound package");
        assert!(
            super::read_saved_sql_search_package(&package_path.to_string_lossy())
                .err()
                .expect("bound seed value rejected")
                .contains("bound chart seed value")
        );

        let case_path = root.join("investigation.case.json");
        let source_path = root.join("contacts.sqlite");
        let source_bytes = b"SQLite source must be preserved";
        std::fs::write(&source_path, source_bytes).expect("write source sentinel");
        let case: CaseFile =
            serde_json::from_str(include_str!("../fixtures/chart/correctness.case.json"))
                .expect("correctness fixture is a valid case");
        let source_search = super::SavedSqlSearch {
            id: Uuid::from_u128(8102),
            name: "Source-bound search".into(),
            database_path: "contacts.sqlite".into(),
            series: "review".into(),
            query: "SELECT source, target FROM contacts".into(),
            parameters: Vec::new(),
            seed_parameter_name: None,
        };
        let mut case = case;
        case.saved_sql_searches.push(source_search.clone());
        assert!(
            super::write_saved_sql_search_package(
                &case,
                &case_path.to_string_lossy(),
                &source_search,
                &source_path.to_string_lossy(),
            )
            .expect_err("export cannot replace source database")
            .contains("saved SQLite source")
        );
        assert_eq!(
            std::fs::read(&source_path).expect("source remains readable"),
            source_bytes
        );
        std::fs::remove_dir_all(root).expect("remove package test directory");
    }

    #[test]
    fn sql_review_package_ui_imports_for_review_and_exports_selected_definition() {
        let root = std::env::temp_dir().join(format!(
            "arch-notebook-sql-search-package-ui-{}",
            Uuid::new_v4()
        ));
        std::fs::create_dir_all(&root).expect("create package UI test directory");
        let package_path = root.join("shared-search.json");
        let package = super::SavedSqlSearchPackage {
            format: "arch-notebook-sql-search".into(),
            schema_version: 1,
            database_base_path: Some(root.to_string_lossy().into_owned()),
            search: super::SavedSqlSearchPackageDefinition {
                name: "Imported contacts".into(),
                database_path: "contacts.sqlite".into(),
                series: "shared review".into(),
                query: "SELECT source, target FROM contacts WHERE owner_id = :entity_id AND state = :state".into(),
                parameters: vec![("state".into(), "text:active".into())],
                seed_parameter_name: Some("entity_id".into()),
            },
        };
        std::fs::write(
            &package_path,
            serde_json::to_vec(&package).expect("serialize UI import package"),
        )
        .expect("write UI import package");
        let case: CaseFile =
            serde_json::from_str(include_str!("../fixtures/chart/correctness.case.json"))
                .expect("correctness fixture is a valid case");
        let case_path = root.join("receiving.case.json");
        let mut app = App::automation_context(case, &case_path.to_string_lossy());
        app.page = super::WorkspacePage::Data;
        app.data_mode = super::DataMode::SqlRegressions;
        app.sql_saved_search_package_import_path = package_path.to_string_lossy().into_owned();
        app.import_saved_sql_search_package();

        assert_eq!(app.case.saved_sql_searches.len(), 1);
        assert_eq!(
            app.sql_saved_search_id,
            app.case.saved_sql_searches.first().map(|s| s.id)
        );
        assert_eq!(app.sql_saved_search_name, "Imported contacts");
        assert_eq!(app.sql_path, root.join("contacts.sqlite").to_string_lossy());
        assert_eq!(app.sql_series, "shared review");
        assert!(app.sql_query.contains(":entity_id"));
        assert_eq!(app.sql_parameter_text, "state=text:active");
        assert_eq!(
            app.sql_review_dynamic_seed_parameter_name.as_deref(),
            Some("entity_id")
        );
        assert!(app.sql_validation_preview.is_none());
        assert!(app.case.snapshots.is_empty());
        assert!(app.status.contains("NOT EXECUTED"));

        let exported_path = root.join("exported.json");
        app.sql_saved_search_package_export_path = exported_path.to_string_lossy().into_owned();
        app.export_saved_sql_search_package();
        let exported = super::read_saved_sql_search_package(&exported_path.to_string_lossy())
            .expect("read exported UI package");
        assert_eq!(exported.search.name, "Imported contacts");
        assert_eq!(
            exported.search.parameters,
            vec![("state".into(), "text:active".into())]
        );
        assert_eq!(
            exported.search.seed_parameter_name.as_deref(),
            Some("entity_id")
        );
        assert!(app.status.starts_with("SQL SEARCH PACKAGE EXPORTED"));

        app.import_saved_sql_search_package();
        assert_eq!(app.case.saved_sql_searches.len(), 1);
        assert!(app.status.contains("already exists"));
        assert!(app.case.snapshots.is_empty());
        std::fs::remove_dir_all(root).expect("remove package UI test directory");
    }

    #[test]
    fn seeded_saved_search_prepares_reviewable_automation_draft_without_creating_job() {
        let case: CaseFile =
            serde_json::from_str(include_str!("../fixtures/chart/correctness.case.json"))
                .expect("correctness fixture parses");
        let search = super::SavedSqlSearch {
            id: Uuid::from_u128(9901),
            name: "Seeded contact lookup".into(),
            database_path: "/tmp/contacts.sqlite".into(),
            series: "contact lookup".into(),
            query: "SELECT source, target FROM contacts WHERE owner_id = :entity_id AND active = :active".into(),
            parameters: vec![
                ("entity_id".into(), "text:stale-chart-id".into()),
                ("active".into(), "bool:true".into()),
            ],
            seed_parameter_name: Some("entity_id".into()),
        };
        let mut case = case;
        case.saved_sql_searches.push(search.clone());
        let mut app = App::automation_context(case, "/tmp/seeded-search.case.json");
        app.page = super::WorkspacePage::Data;
        app.data_mode = super::DataMode::SqlRegressions;
        app.sql_saved_search_id = Some(search.id);
        app.sql_loaded_saved_search_id = Some(search.id);
        app.sql_saved_search_name = search.name.clone();
        app.sql_path = search.database_path.clone();
        app.sql_series = search.series.clone();
        app.sql_query = search.query.clone();
        app.sql_parameter_text = "entity_id=text:stale-chart-id\nactive=bool:true".into();
        app.sql_seed_query_mode = true;
        app.sql_review_dynamic_seed_parameter_name = Some("entity_id".into());
        app.sql_seed_page_offset = 200;
        app.sql_validation_preview = Some(super::SqlValidationPreview {
            configured_database_path: app.sql_path.clone(),
            series: app.sql_series.clone(),
            query: app.sql_query.clone(),
            parameters: vec![
                ("entity_id".into(), "text:stale-chart-id".into()),
                ("active".into(), "bool:true".into()),
            ],
            seeded_query: true,
            validation_passed: true,
            ..Default::default()
        });

        app.prepare_saved_sql_search_for_automation();

        assert_eq!(app.sql_path, search.database_path);
        assert_eq!(app.sql_series, search.series);
        assert_eq!(app.sql_query, search.query);
        assert_eq!(app.sql_parameter_text, "active=bool:true");
        assert!(!app.sql_seed_query_mode);
        assert!(app.sql_review_dynamic_seed_parameter_name.is_none());
        assert_eq!(app.sql_seed_page_offset, 0);
        assert!(app.sql_validation_preview.is_none());
        assert!(app.case.automation_jobs.is_empty());
        assert_eq!(app.automation_job_name, "Seeded contact lookup automation");
        assert!(app.status.contains("predicate was kept"));

        app.sql_parameter_text = "entity_id=text:another-stale-id\nactive=bool:true".into();
        app.prepare_saved_sql_search_for_automation();
        assert_eq!(app.sql_parameter_text, "active=bool:true");
        assert!(app.case.automation_jobs.is_empty());
    }

    #[test]
    fn saved_sql_search_automation_draft_requires_loaded_selection_and_keeps_unseeded_parameters() {
        let mut case: CaseFile =
            serde_json::from_str(include_str!("../fixtures/chart/correctness.case.json"))
                .expect("correctness fixture parses");
        let search = super::SavedSqlSearch {
            id: Uuid::from_u128(9902),
            name: "Monthly contacts".into(),
            database_path: "/tmp/monthly.sqlite".into(),
            series: "monthly contacts".into(),
            query: "SELECT source, target FROM contacts WHERE active = :active".into(),
            parameters: vec![("active".into(), "bool:true".into())],
            seed_parameter_name: None,
        };
        case.saved_sql_searches.push(search.clone());
        let mut app = App::automation_context(case, "/tmp/monthly-search.case.json");
        app.page = super::WorkspacePage::Data;
        app.data_mode = super::DataMode::SqlRegressions;
        app.sql_saved_search_id = Some(search.id);
        app.sql_query = "SELECT source, target FROM unrelated_draft".into();
        app.sql_parameter_text = "wrong=value".into();

        app.prepare_saved_sql_search_for_automation();

        assert!(app.status.contains("LOAD THE SELECTED SAVED SEARCH FIRST"));
        assert_eq!(app.sql_query, "SELECT source, target FROM unrelated_draft");
        assert_eq!(app.sql_parameter_text, "wrong=value");
        assert!(app.case.automation_jobs.is_empty());

        app.load_sql_review_search();
        assert_eq!(app.sql_loaded_saved_search_id, Some(search.id));
        app.sql_query.push_str(" ORDER BY source, target");
        app.sql_validation_preview = Some(super::SqlValidationPreview {
            configured_database_path: app.sql_path.clone(),
            series: app.sql_series.clone(),
            query: app.sql_query.clone(),
            parameters: vec![("active".into(), "bool:true".into())],
            validation_passed: true,
            ..Default::default()
        });

        app.prepare_saved_sql_search_for_automation();

        assert_eq!(app.sql_parameter_text, "active=bool:true");
        assert!(app.sql_query.ends_with("ORDER BY source, target"));
        assert!(app.sql_validation_preview.is_none());
        assert_eq!(app.automation_job_name, "Monthly contacts automation");
        assert!(app.status.contains("saved SQL parameters were kept"));
        assert!(app.case.automation_jobs.is_empty());
        assert!(app.case.snapshots.is_empty());
    }

